def run(cmds):
    state = 'start'
    out = []
    for c in cmds:
        if state == 'start':
            if c == 'go':
                state = 'run'
            out.append('start:' + c)
        elif state == 'run':
            if c == 'stop':
                state = 'done'
            else:
                out.append('run:' + c)
        else:
            out.append('done:' + c)
    return state, out
print(run(['go', 'a', 'b', 'stop', 'c']))

